func commonPrefix(a, b string) string {
    minLength := len(a)
    if len(b) < minLength {
        minLength = len(b)
    }
    sum := ""
    for i := 0; i < minLength; i++ {
        if a[i] != b[i] {
            return sum
        }
        sum += string(a[i])
    }
    return sum
}

